import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge class names with Tailwind-aware conflict resolution. */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

/** Selects the message catalogue the library renders its own default strings from, and exposes locale-bound Intl formatters, so a page in Arabic, French or Hindi needs no per-component label props. */
import * as React from "react";
import {
  DEFAULT_LOCALE,
  formatMessage,
  getMessages,
  type MessageKey,
  type Messages,
  type MessageVars,
} from "./messages";
import { directionOf, type Direction } from "@/hooks/use-locale";

export type { MessageKey, Messages, MessageVars };
export type { BuiltInLocale, MessageValue, PluralForms } from "./messages";
export { BUILT_IN_LOCALES, DEFAULT_LOCALE, MESSAGES, getMessages, hasMessages } from "./messages";
/**
 * The plural-and-interpolation primitive, exported so an application can run
 * its own catalogue through the same rules the library uses rather than
 * reaching for a second i18n implementation alongside this one.
 */
export { formatMessage, isPluralForms } from "./messages";

/** Looks a message up and returns it ready to render. */
export type TranslateFn = (key: MessageKey, vars?: MessageVars) => string;

export interface I18nContextValue {
  /** The active BCP 47 tag, e.g. `ar`, `fr-CA`. */
  locale: string;
  /** The resolved catalogue, including any `messages` override. */
  messages: Messages;
  t: TranslateFn;
  /** Writing direction of `locale`, for components that need it in JS. */
  dir: Direction;
}

/**
 * No provider means English.
 *
 * That default is what keeps this addition non-breaking: every component below
 * renders exactly the strings it rendered before unless something above it
 * asks for another language.
 */
const I18nContext = React.createContext<I18nContextValue | null>(null);

export interface I18nProviderProps {
  /** BCP 47 tag. Falls back to the language subtag, then to English. */
  locale?: string;
  /**
   * Overrides merged over the built-in catalogue, so an app can reword one
   * string — or add a language the library does not ship — without forking a
   * whole catalogue.
   */
  messages?: Partial<Messages>;
  children?: React.ReactNode;
}

/**
 * Provides the catalogue for `locale` to everything below it.
 *
 * Pairs with `useLocale`, which owns `<html lang>` and `<html dir>`: that hook
 * decides how the document is laid out and which font stack the base layer
 * picks, this provider decides which words are in it. They are separate on
 * purpose — an app already running next-intl can keep its own strings and use
 * `useLocale` alone, and neither half needs the other to work.
 */
function I18nProvider({ locale = DEFAULT_LOCALE, messages, children }: I18nProviderProps) {
  const value = React.useMemo<I18nContextValue>(() => {
    const base = getMessages(locale);
    // A new object only when there is actually an override to merge; otherwise
    // the catalogue is the shared frozen module object.
    const resolved = messages ? { ...base, ...messages } : base;

    return {
      locale,
      messages: resolved,
      dir: directionOf(locale),
      t: (key, vars) => formatMessage(resolved[key], locale, vars),
    };
  }, [locale, messages]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

/** The English catalogue, built once, for every subtree with no provider. */
const fallback: I18nContextValue = {
  locale: DEFAULT_LOCALE,
  messages: getMessages(DEFAULT_LOCALE),
  dir: "ltr",
  t: (key, vars) => formatMessage(getMessages(DEFAULT_LOCALE)[key], DEFAULT_LOCALE, vars),
};

/** The active locale, its catalogue, its direction and `t`. */
export function useI18n(): I18nContextValue {
  return React.useContext(I18nContext) ?? fallback;
}

/**
 * Just the translate function, which is what a component almost always wants:
 *
 * ```tsx
 * const t = useT();
 * const closeLabel = closeLabelProp ?? t("dialog.close");
 * ```
 *
 * The prop stays ahead of the catalogue, so an explicit label always wins.
 */
export function useT(): TranslateFn {
  return useI18n().t;
}

/**
 * Translation for code that runs outside the React tree — `notify.copied()`
 * and any other imperative helper, which has no context to read from.
 *
 * Takes the language from `<html lang>`, kept current by `useLocale` or by the
 * route that rendered the document. That is only sound because these call
 * sites are browser-only by nature: a toast has nowhere to appear on a server,
 * so there is no shared-document hazard here of the kind a module-level locale
 * would create. Inside a component, use `useT` instead.
 */
export function translateStandalone(key: MessageKey, vars?: MessageVars): string {
  const locale =
    typeof document === "undefined"
      ? DEFAULT_LOCALE
      : document.documentElement.lang || DEFAULT_LOCALE;
  return formatMessage(getMessages(locale)[key], locale, vars);
}

export interface Formatters {
  number: Intl.NumberFormat;
  date: Intl.DateTimeFormat;
  time: Intl.DateTimeFormat;
  relativeTime: Intl.RelativeTimeFormat;
  list: Intl.ListFormat;
}

/**
 * `Intl` formatters bound to the active locale, so a figure in a stat card or
 * a date in a table follows the reader's language along with the words around
 * it. Memoised per locale, since constructing these is the expensive part.
 */
export function useFormatters(): Formatters {
  const { locale } = useI18n();

  return React.useMemo(
    () => ({
      number: new Intl.NumberFormat(locale),
      date: new Intl.DateTimeFormat(locale, { dateStyle: "medium" }),
      time: new Intl.DateTimeFormat(locale, { timeStyle: "short" }),
      relativeTime: new Intl.RelativeTimeFormat(locale, { numeric: "auto" }),
      list: new Intl.ListFormat(locale),
    }),
    [locale],
  );
}

export { I18nProvider };

/**
 * The built-in catalogues and the lookup that picks one for a locale.
 *
 * Deliberately not a client module. `I18nProvider` and the hooks next door are
 * `"use client"`, and a plain function exported from a client module cannot be
 * called on the server at all. Keeping the catalogues here means a server
 * component, a route handler, a metadata export or a build script can read
 * them directly — `getMessages("ar")["dialog.close"]` works anywhere.
 */
import { en, type MessageKey, type Messages } from "./en";
import { ar } from "./ar";
import { fr } from "./fr";
import { hi } from "./hi";

export type { MessageKey, Messages };
export type { MessageValue, MessageVars, PluralForms } from "./types";
export { formatMessage, isPluralForms } from "./types";
export { en, ar, fr, hi };

/** Every language the library ships strings for, keyed by language subtag. */
export const MESSAGES = { en, ar, fr, hi } as const;

/** The subtags `MESSAGES` covers. A locale outside this set falls back to `en`. */
export type BuiltInLocale = keyof typeof MESSAGES;

export const BUILT_IN_LOCALES = Object.keys(MESSAGES) as BuiltInLocale[];

/** The catalogue used when a locale has none of its own. */
export const DEFAULT_LOCALE: BuiltInLocale = "en";

/** Narrows a free-form tag to one of the shipped catalogues. */
export function hasMessages(locale: string): locale is BuiltInLocale {
  return locale in MESSAGES;
}

/**
 * The catalogue for a locale.
 *
 * Matches the full tag first and then the language subtag, so `fr-CA` and
 * `ar-EG` land on French and Arabic rather than silently falling back to
 * English. Anything with no catalogue at all returns English, because a page
 * in the wrong language still reads; a page of missing-key placeholders does
 * not.
 */
export function getMessages(locale: string): Messages {
  if (hasMessages(locale)) return MESSAGES[locale];
  const language = locale.toLowerCase().split(/[-_]/)[0] ?? "";
  return hasMessages(language) ? MESSAGES[language] : MESSAGES[DEFAULT_LOCALE];
}

/**
 * The shape of a message catalogue, and the pure function that turns one entry
 * into a finished string.
 *
 * Kept free of React and of any `"use client"` directive on purpose: a server
 * component, a route handler or a build script can import this and read the
 * catalogues directly, which a client module would not allow.
 */

/**
 * A message whose wording changes with a number.
 *
 * The keys are CLDR plural categories, and which ones a language actually uses
 * is decided by `Intl.PluralRules`, not by us: English uses `one` and `other`,
 * French adds `many`, Hindi uses the same two as English, and Arabic uses all
 * six. `other` is required because it is the only category every language has,
 * so it is always there to fall back to.
 */
export type PluralForms = Partial<Record<Intl.LDMLPluralRule, string>> & { other: string };

/** Either a fixed string, or the set of forms a count selects between. */
export type MessageValue = string | PluralForms;

/** Values substituted into `{placeholder}` slots. */
export type MessageVars = Record<string, string | number>;

const PLACEHOLDER = /\{(\w+)\}/g;

/**
 * `Intl` constructors are not cheap and these are called on every render, so
 * each locale's rules are built once. Nothing here is per-user state — the
 * cache is keyed by the locale tag alone — so it is safe to share across
 * requests on a server.
 */
const pluralRules = new Map<string, Intl.PluralRules>();
const numberFormats = new Map<string, Intl.NumberFormat>();

function pluralRulesFor(locale: string): Intl.PluralRules {
  let rules = pluralRules.get(locale);
  if (!rules) {
    rules = new Intl.PluralRules(locale);
    pluralRules.set(locale, rules);
  }
  return rules;
}

function numberFormatFor(locale: string): Intl.NumberFormat {
  let format = numberFormats.get(locale);
  if (!format) {
    format = new Intl.NumberFormat(locale);
    numberFormats.set(locale, format);
  }
  return format;
}

/** True when the entry is a set of plural forms rather than one fixed string. */
export function isPluralForms(value: MessageValue): value is PluralForms {
  return typeof value !== "string";
}

/**
 * Picks the plural form for `count` and substitutes every `{placeholder}`.
 *
 * Numbers go through `Intl.NumberFormat` for the locale, which decides the
 * digits. Worth knowing before picking a tag: CLDR gives bare `ar` the Latin
 * digits most Arabic interfaces use, while the regional tags default to
 * Arabic-Indic — `ar` formats 2 as "2", `ar-EG` as "٢". Either is one tag
 * away (`ar-u-nu-arab`, `ar-EG-u-nu-latn`), which is the standard way to ask
 * and needs no option of ours.
 *
 * A placeholder with no matching variable is left as written rather than
 * blanked: a visible `{name}` in the UI points at the missing variable, where
 * an empty gap just looks like a layout bug.
 */
export function formatMessage(value: MessageValue, locale: string, vars?: MessageVars): string {
  let template: string;

  if (isPluralForms(value)) {
    const count = Number(vars?.count ?? 0);
    const category = pluralRulesFor(locale).select(count);
    template = value[category] ?? value.other;
  } else {
    template = value;
  }

  if (!vars) return template;

  return template.replace(PLACEHOLDER, (whole, name: string) => {
    const replacement = vars[name];
    if (replacement === undefined) return whole;
    return typeof replacement === "number"
      ? numberFormatFor(locale).format(replacement)
      : replacement;
  });
}

"use client";

/** Vertically stacked disclosure sections; the open panel animates its height and its chevron flips. */
import * as React from "react";
import { ChevronDown } from "lucide-react";
import { Accordion as AccordionPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";

export type AccordionProps = React.ComponentProps<typeof AccordionPrimitive.Root>;

function Accordion({ className, ...props }: AccordionProps) {
  return <AccordionPrimitive.Root data-slot="accordion" className={cn(className)} {...props} />;
}

function AccordionItem({
  className,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Item>) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn("border-b border-border last:border-b-0", className)}
      {...props}
    />
  );
}

function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Trigger>) {
  return (
    <AccordionPrimitive.Header className="flex" data-slot="accordion-header">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "group/accordion-trigger flex flex-1 items-start justify-between gap-4",
          "py-4 text-start text-sm font-medium",
          "transition-[color,box-shadow] duration-(--duration-fast) ease-standard",
          "outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring",
          "disabled:pointer-events-none disabled:opacity-50",
          className,
        )}
        {...props}
      >
        {children}
        <ChevronDown
          data-slot="accordion-chevron"
          className={cn(
            "pointer-events-none size-4 shrink-0 translate-y-0.5 text-muted-foreground",
            "motion-safe:transition-transform motion-safe:duration-(--duration-fast) motion-safe:ease-standard",
            "group-data-[state=open]/accordion-trigger:rotate-180",
          )}
        />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Content>) {
  return (
    <AccordionPrimitive.Content
      data-slot="accordion-content"
      className={cn(
        "overflow-hidden text-sm",
        // Radix publishes --radix-accordion-content-height; the keyframes that
        // consume it live in the token layer so every component shares them.
        "motion-safe:data-[state=open]:animate-accordion-down",
        "motion-safe:data-[state=closed]:animate-accordion-up",
      )}
      {...props}
    >
      <div className={cn("pb-4 pt-0 text-muted-foreground", className)}>{children}</div>
    </AccordionPrimitive.Content>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

"use client";

/** Blocking confirmation dialog with a destructive-safe action and a cancel button; it cannot be dismissed by clicking the overlay. */
import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "radix-ui";
import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";

function AlertDialog(props: React.ComponentProps<typeof AlertDialogPrimitive.Root>) {
  return <AlertDialogPrimitive.Root {...props} />;
}

function AlertDialogTrigger({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Trigger>) {
  return (
    <AlertDialogPrimitive.Trigger
      data-slot="alert-dialog-trigger"
      className={cn(className)}
      {...props}
    />
  );
}

function AlertDialogPortal(props: React.ComponentProps<typeof AlertDialogPrimitive.Portal>) {
  return <AlertDialogPrimitive.Portal {...props} />;
}

function AlertDialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Overlay>) {
  return (
    <AlertDialogPrimitive.Overlay
      data-slot="alert-dialog-overlay"
      className={cn(
        "fixed inset-0 z-(--z-overlay) bg-overlay",
        "motion-safe:transition-opacity motion-safe:duration-(--duration-fast) motion-safe:ease-standard",
        "data-[state=open]:opacity-100 data-[state=closed]:opacity-0",
        "motion-safe:data-[state=open]:animate-fade-in",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogContent({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Content>) {
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Content
        data-slot="alert-dialog-content"
        className={cn(
          "fixed top-1/2 start-1/2 z-(--z-modal) w-full max-w-lg",
          // `start-1/2` resolves to the right edge in RTL, so the centring
          // transform has to mirror with it.
          "-translate-x-1/2 -translate-y-1/2 rtl:translate-x-1/2",
          "grid gap-4 rounded-card border bg-card p-6 text-card-foreground shadow-3",
          "outline-none",
          "motion-safe:transition-opacity motion-safe:duration-(--duration-fast) motion-safe:ease-standard",
          "data-[state=open]:opacity-100 data-[state=closed]:opacity-0",
          "motion-safe:data-[state=open]:animate-scale-in",
          className,
        )}
        {...props}
      />
    </AlertDialogPortal>
  );
}

function AlertDialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn("flex flex-col gap-1.5 text-start", className)}
      {...props}
    />
  );
}

function AlertDialogFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
      {...props}
    />
  );
}

function AlertDialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Title>) {
  return (
    <AlertDialogPrimitive.Title
      data-slot="alert-dialog-title"
      className={cn("text-h4 font-semibold leading-none tracking-tight", className)}
      {...props}
    />
  );
}

function AlertDialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Description>) {
  return (
    <AlertDialogPrimitive.Description
      data-slot="alert-dialog-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

function AlertDialogAction({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Action>) {
  return (
    <AlertDialogPrimitive.Action
      data-slot="alert-dialog-action"
      className={cn(buttonVariants(), className)}
      {...props}
    />
  );
}

function AlertDialogCancel({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Cancel>) {
  return (
    <AlertDialogPrimitive.Cancel
      data-slot="alert-dialog-cancel"
      className={cn(buttonVariants({ variant: "outline" }), className)}
      {...props}
    />
  );
}

export {
  AlertDialog,
  AlertDialogTrigger,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogAction,
  AlertDialogCancel,
};

/** Inline status message. A grid keeps an optional leading icon aligned with the title while the description wraps under both. */
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const alertVariants = cva(
  [
    // One icon column that collapses to zero width when no icon is present, so
    // the title always starts flush with the padding in the icon-less case.
    "relative grid w-full grid-cols-[0_1fr] items-start gap-y-0.5",
    "has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg]:gap-x-3",
    "rounded-card border px-4 py-3 text-sm",
    "[&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current",
  ],
  {
    variants: {
      variant: {
        default: "border-border bg-card text-card-foreground",
        destructive:
          "border-destructive/30 bg-destructive/10 text-destructive *:data-[slot=alert-description]:text-destructive/90",
        success:
          "border-success/30 bg-success/10 text-success-700 dark:text-success-300 *:data-[slot=alert-description]:opacity-90",
        warning:
          "border-warning/30 bg-warning/10 text-warning-700 dark:text-warning-300 *:data-[slot=alert-description]:opacity-90",
        info: "border-info/30 bg-info/10 text-info-700 dark:text-info-300 *:data-[slot=alert-description]:opacity-90",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface AlertProps
  extends React.ComponentProps<"div">, VariantProps<typeof alertVariants> {}

function Alert({ className, variant, ...props }: AlertProps) {
  return (
    <div
      data-slot="alert"
      data-variant={variant ?? "default"}
      role="alert"
      className={cn(alertVariants({ variant }), className)}
      {...props}
    />
  );
}

function AlertTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-title"
      className={cn("col-start-2 min-h-4 font-medium tracking-tight", className)}
      {...props}
    />
  );
}

function AlertDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn(
        "col-start-2 grid justify-items-start gap-1 text-sm text-muted-foreground",
        "[&_p]:leading-relaxed",
        className,
      )}
      {...props}
    />
  );
}

export { Alert, AlertTitle, AlertDescription, alertVariants };

"use client";

/** Round user image that falls back to initials on a muted disc while the image loads or fails. */
import * as React from "react";
import { Avatar as AvatarPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";

export type AvatarProps = React.ComponentProps<typeof AvatarPrimitive.Root>;

function Avatar({ className, ...props }: AvatarProps) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      className={cn(
        "relative flex size-10 shrink-0 overflow-hidden rounded-avatar select-none",
        className,
      )}
      {...props}
    />
  );
}

function AvatarImage({ className, ...props }: React.ComponentProps<typeof AvatarPrimitive.Image>) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn("aspect-square size-full object-cover", className)}
      {...props}
    />
  );
}

function AvatarFallback({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Fallback>) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        "flex size-full items-center justify-center rounded-avatar bg-muted",
        "text-sm font-medium text-muted-foreground uppercase",
        className,
      )}
      {...props}
    />
  );
}

export { Avatar, AvatarImage, AvatarFallback };

/** Small status or category label. Status variants use their own colour ramps, so they stay readable even when the brand colour is itself red. */
import * as React from "react";
import { Slot } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const badgeVariants = cva(
  [
    "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden whitespace-nowrap",
    "rounded-badge border px-2 py-0.5 text-xs font-medium",
    "transition-[color,background-color,border-color] duration-(--duration-fast) ease-standard",
    "focus-visible:ring-2 focus-visible:ring-ring/50 [&>svg]:pointer-events-none [&>svg]:size-3",
  ],
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground [a&]:hover:bg-primary-hover",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/80",
        outline:
          "border-border text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground [a&]:hover:bg-destructive/90",
        success: "border-transparent bg-success text-success-foreground",
        warning: "border-transparent bg-warning text-warning-foreground",
        info: "border-transparent bg-info text-info-foreground",
        soft: "border-transparent bg-primary/12 text-primary dark:bg-primary/20",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps
  extends React.ComponentProps<"span">, VariantProps<typeof badgeVariants> {
  asChild?: boolean;
}

function Badge({ className, variant, asChild = false, ...props }: BadgeProps) {
  const Comp = asChild ? Slot.Root : "span";
  return (
    <Comp
      data-slot="badge"
      data-variant={variant ?? "default"}
      className={cn(badgeVariants({ variant }), className)}
      {...props}
    />
  );
}

export { Badge, badgeVariants };

"use client";

/** Trail of ancestor links ending in the current page. The separator chevron points along the reading direction. */
import * as React from "react";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import { Slot } from "radix-ui";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";

function Breadcrumb({ className, ...props }: React.ComponentProps<"nav">) {
  const t = useT();

  return (
    <nav
      data-slot="breadcrumb"
      aria-label={t("breadcrumb.label")}
      className={cn(className)}
      {...props}
    />
  );
}

function BreadcrumbList({ className, ...props }: React.ComponentProps<"ol">) {
  return (
    <ol
      data-slot="breadcrumb-list"
      className={cn(
        "flex flex-wrap items-center gap-1.5 break-words text-sm text-muted-foreground sm:gap-2.5",
        className,
      )}
      {...props}
    />
  );
}

function BreadcrumbItem({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-item"
      className={cn("inline-flex items-center gap-1.5", className)}
      {...props}
