function Sidebar({
  className,
  children,
  label: labelProp,
  mobileDescription: mobileDescriptionProp,
  ...props
}: SidebarProps) {
  const t = useT();
  const label = labelProp ?? t("sidebar.label");
  const mobileDescription = mobileDescriptionProp ?? t("sidebar.mobileDescription");

  const { state, isMobile, openMobile, setOpenMobile, direction } = useSidebar();

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile}>
        <SheetContent
          side="start"
          data-slot="sidebar"
          data-mobile="true"
          className={cn(
            "group/sidebar w-(--sidebar-w) max-w-[85vw] gap-0 border-sidebar-border bg-sidebar p-0 text-sidebar-foreground",
            className,
