                          "text-sidebar-accent-foreground",
                          "group-data-[state=collapsed]/sidebar:hidden",
                        )}
                      >
                        {item.badge}
                      </span>
                    ) : null}
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroup>
          ))}
        </SidebarContent>

        {sidebarFooter ? <SidebarFooter>{sidebarFooter}</SidebarFooter> : null}
      </Sidebar>

      <SidebarInset>
        <header
          data-slot="dashboard-shell-topbar"
          className={cn(
